add_action( 'woocommerce_checkout_order_processed', 'perfectpixel_notify_email_new_order', 20, 3 );

function perfectpixel_notify_email_new_order( $order_id, $posted_data, $order ) {
	$to = sanitize_email( '{{notify_email}}' );
	if ( ! is_email( $to ) || ! $order instanceof WC_Order ) {
		return;
	}
	$lines = array(
		$order->get_formatted_billing_full_name(),
		$order->get_billing_email(),
		$order->get_billing_phone(),
		'',
		wp_strip_all_tags( str_replace( '<br/>', "\n", (string) $order->get_formatted_shipping_address( $order->get_formatted_billing_address() ) ) ),
		'',
		admin_url( 'post.php?post=' . $order->get_id() . '&action=edit' ),
	);
	wp_mail( $to, sprintf( '{{notify_subject}}', $order->get_order_number() ), implode( "\n", $lines ) );
}
